with c as (select id, content, position($x$<h3>Mad A104 | Giorgio Armani Acqua Di Gio Absolu Muadili</h3>$x$ in content) s from blog_posts where slug='mad-parfum-muadil-listesi'),
c2 as (select id, content, s, s + 4 + position('<h3>' in substring(content from s+4)) - 1 e from c)
update blog_posts b set content = substring(c2.content from 1 for c2.s-1) || (select replace(replace(replace(substring(content from s for e-s), $x$<p>Deniz notalarının ferahlığı ile meyveli bir tatlılığı aynı şişede buluşturan <a target="_self" class="text-blue-600 underline decoration-blue-300 font-medium" href="https://uygunbakim.com/product/mad-parfum-a104-selective"><strong><u>Mad A104</u></strong></a>, alışılmış su kokularının ötesine geçerek daha derin bir hikaye anlatıyor. Açılıştaki limon ve bergamotun keskin enerjisi, orta notalarda yer alan biberiye ve lavantanın aromatik dokusuyla birleşerek parfüme maskülen ve dengeli bir omurga kazandırıyor.</p>$x$, ''), $x$<p>Tene yerleştiğinde ise paçuli ve tonka fasulyesinin yarattığı o sıcak, odunsu derinlik kendini hissettirmeye başlıyor. %77 nota benzerliği ile deniz tuzu ve toprak kokusunu bir araya getiren <a target="_self" class="text-blue-600 underline decoration-blue-300 font-medium" href="https://uygunbakim.com/product/giorgio-armani-acqua-di-gio-absolu"><strong><u>Acqua Di Gio Absolu</u></strong></a> karakterini başarıyla yansıtan bu koku, hem taze hem de oturaklı bir imza arayanlar için ideal bir günlük eşlikçi.</p>$x$, ''), $x$<div data-id="24361" data-type="muadil-card"></div>$x$, $x$<div data-id="24361" data-type="muadil-card"></div><p><a target="_self" class="text-blue-600 underline decoration-blue-300 font-medium" href="https://uygunbakim.com/product/mad-parfum-a104-selective"><strong><u>Mad A104</u></strong></a>, <a target="_self" class="text-blue-600 underline decoration-blue-300 font-medium" href="https://uygunbakim.com/product/giorgio-armani-acqua-di-gio-absolu"><strong><u>Giorgio Armani Acqua Di Gio Absolu</u></strong></a>'nun muadilidir (%77 nota benzerliği). Limon ve bergamotlu açılış, sardunya, lavanta ve biberiyeli kalp, paçuli, tonka ve amberli dip iki parfümde de ortak. Fark: Acqua Di Gio Absolu'daki deniz notaları, armut, elma ve greyfurt A104'te yok; A104 bunların yerine meyveli notalar taşır.</p>$x$) from c2 x where x.id=c2.id) || substring(c2.content from c2.e), updated_at = now()
from c2 where b.id = c2.id and c2.s > 0 and position($x$<p>Deniz notalarının ferahlığı ile meyveli bir tatlılığı aynı şişede buluşturan <a target="_self" class="text-blue-600 underline decoration-blue-300 font-medium" href="https://uygunbakim.com/product/mad-parfum-a104-selective"><strong><u>Mad A104</u></strong></a>, alışılmış su kokularının ötesine geçerek daha derin bir hikaye anlatıyor. Açılıştaki limon ve bergamotun keskin enerjisi, orta notalarda yer alan biberiye ve lavantanın aromatik dokusuyla birleşerek parfüme maskülen ve dengeli bir omurga kazandırıyor.</p>$x$ in substring(c2.content from c2.s for c2.e-c2.s))>0 and position($x$<p>Tene yerleştiğinde ise paçuli ve tonka fasulyesinin yarattığı o sıcak, odunsu derinlik kendini hissettirmeye başlıyor. %77 nota benzerliği ile deniz tuzu ve toprak kokusunu bir araya getiren <a target="_self" class="text-blue-600 underline decoration-blue-300 font-medium" href="https://uygunbakim.com/product/giorgio-armani-acqua-di-gio-absolu"><strong><u>Acqua Di Gio Absolu</u></strong></a> karakterini başarıyla yansıtan bu koku, hem taze hem de oturaklı bir imza arayanlar için ideal bir günlük eşlikçi.</p>$x$ in substring(c2.content from c2.s for c2.e-c2.s))>0
returning b.id, length(b.content);